std::generator<std::string_view> split_lines(std::string_view payload) {
  std::size_t start = 0;
  for (std::size_t i = 0; i <= payload.size(); ++i)
    if (i == payload.size() || payload[i] == '\n') {
      co_yield payload.substr(start, i - start);
      start = i + 1;
    }
}
